BEGIN;
DO $s14$
DECLARE p jsonb; q jsonb; e jsonb; cd text; lid int; n int:=0; b_leg jsonb; b_bridge jsonb; b_pub jsonb; b_dep jsonb; b_judge jsonb; b_cand int; b_orig jsonb; b_apps jsonb;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_leg FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY legacy_id,nucleo_codigo,version_nucleo) INTO b_bridge FROM lf_ops.lf_nucleo_cobertura_legada t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_pub FROM lf_ops.nucleo_regla_versiones t WHERE estado='PUBLICADA';
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_judge FROM lf_ops.nucleo_juicios t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_orig FROM lf_ops.nucleo_regla_versiones t WHERE regla IN ('S13-C04','S13-C10','S13-C11','S13-C12','S13-C13','S13-C14','S13-C15');
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,nodo) INTO b_apps FROM lf_ops.nucleo_aplicaciones t WHERE regla IN ('S13-C04','S13-C10','S13-C11','S13-C12','S13-C13','S13-C14','S13-C15');
 SELECT count(*) INTO b_cand FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA';
 IF EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S14-C%') THEN RAISE EXCEPTION 'S14_CANDIDATES_ALREADY_EXIST'; END IF;
